def _split_setting(line: str) -> tuple[str, str] | None:
    """Split a stripped setting line at its first ``=`` or ``:``."""
    equals = line.find("=")
    colon = line.find(":")
    if equals == -1 and colon == -1:
        return None
    if colon == -1 or (equals != -1 and equals < colon):
        index = equals
    else:
        index = colon
    return line[:index].strip(), line[index + 1 :].strip()


def _interpolate(
    value: str,
    section: str,
    sections: dict[str, dict[str, str]],
    cache: dict[tuple[str, str], str],
    stack: list[tuple[str, str]],
) -> str:
    """Expand references in ``value``, which belongs to ``section``."""
    pieces: list[str] = []
    index = 0
    while index < len(value):
        if value[index] != "$":
            next_dollar = value.find("$", index)
            if next_dollar == -1:
                pieces.append(value[index:])
                break
            pieces.append(value[index:next_dollar])
            index = next_dollar
        elif value.startswith("$$", index):
            pieces.append("$")
            index += 2
        elif value.startswith("${", index):
            end = value.find("}", index + 2)
            if end == -1:
                # An unterminated reference is just a literal dollar sign.
                pieces.append("$")
                index += 1
            else:
                reference = value[index + 2 : end]
                if ":" in reference:
                    # Keys cannot contain ':', so the last colon separates
                    # the section from the key.
                    ref_section, ref_key = reference.rsplit(":", 1)
                else:
                    ref_section, ref_key = section, reference
                pieces.append(
                    _lookup(sections, ref_section, ref_key.lower(), cache, stack)
                )
                index = end + 1
        else:
            pieces.append("$")
            index += 1
    return "".join(pieces)


def _lookup(
    sections: dict[str, dict[str, str]],
    section: str,
    key: str,
    cache: dict[tuple[str, str], str],
    stack: list[tuple[str, str]],
) -> str:
    """Return the fully interpolated value of ``key`` in ``section``."""
    if section not in sections:
        raise InterpolationError(f"no section {section!r}")
    values = sections[section]
    if key not in values:
        raise InterpolationError(f"no key {key!r} in section {section!r}")

    identity = (section, key)
    if identity in cache:
        return cache[identity]
    if identity in stack:
        path = " -> ".join(f"[{name}] {item}" for name, item in stack + [identity])
        raise InterpolationError(f"interpolation cycle: {path}")

    stack.append(identity)
    try:
        expanded = _interpolate(values[key], section, sections, cache, stack)
    finally:
        stack.pop()
    cache[identity] = expanded
    return expanded


def parse(text: str) -> dict[str, dict[str, str]]:
    """Parse INI text."""
    sections: dict[str, dict[str, str]] = {}
    current_section: str | None = None
    continuing: str | None = None

    for lineno, raw_line in enumerate(text.splitlines(), 1):
        line = raw_line.strip()

        # Blank lines and comments end any continuation.
        if not line or line[0] in "#;":
            continuing = None
            continue

        # A whitespace-prefixed line continues the previous key, unless the
        # previous line was not a key or continuation.
        if raw_line[:1].isspace() and continuing is not None:
            assert current_section is not None
            sections[current_section][continuing] += "\n" + line
            continue

        if line.startswith("["):
            if not line.endswith("]"):
                raise ParseError(lineno, "malformed section header")
            name = line[1:-1].strip()
            current_section = name
            sections.setdefault(name, {})
            continuing = None
            continue

        setting = _split_setting(line)
        if setting is None:
            raise ParseError(lineno, "expected a section or 'key = value'")
        key, value = setting
        if not key:
            raise ParseError(lineno, "empty key")
        if current_section is None:
            raise ParseError(lineno, "key outside a section")

        key = key.lower()
        sections[current_section][key] = value
        continuing = key

    cache: dict[tuple[str, str], str] = {}
    result: dict[str, dict[str, str]] = {}
    for section, values in sections.items():
        expanded: dict[str, str] = {}
        for key in values:
            expanded[key] = _lookup(sections, section, key, cache, [])
        result[section] = expanded
    return result
